j = Stateflow.Junction(ch); j.Position.Center = [220 40]; j.Position.Radius = 10;

t1 = Stateflow.Transition(ch); t1.Source=off; t1.Destination=on;  t1.LabelString='[T < 18]';
t2 = Stateflow.Transition(ch); t2.Source=on;  t2.Destination=off; t2.LabelString='[T > 22]';
save_system('tempCtl');

