tools.example:
sfnew('-MATLAB','seq');
ch = find(sfroot,'-isa','Stateflow.Chart');

names = {'Init','Warmup','Run','Shutdown'};
prev = [];
for k = 1:numel(names)
    s = Stateflow.State(ch);
    s.Name = names{k};
    s.Position = [40, 40 + 110*(k-1), 140, 70];
    s.LabelString = sprintf('%s\nentry: step = %d;', names{k}, k);
    if ~isempty(prev)
        t = Stateflow.Transition(ch);
        t.Source = prev; t.Destination = s;
        t.LabelString = sprintf('after(2, sec)');
    end
    prev = s;
end
save_system('seq');

